interface VersionVector {
  [datacenterId: string]: number; // e.g., { 'us-east': 4, 'eu-central': 2 }
}

export function detectConflict(v1: VersionVector, v2: VersionVector): 'CONCURRENT_CONFLICT' | 'V1_DOMINATES' | 'V2_DOMINATES' {
  let v1Greater = false;
  let v2Greater = false;
  const allKeys = new Set([...Object.keys(v1), ...Object.keys(v2)]);

  for (const k of allKeys) {
    const count1 = v1[k] || 0;
    const count2 = v2[k] || 0;
    if (count1 > count2) v1Greater = true;
    if (count2 > count1) v2Greater = true;
  }

  if (v1Greater && v2Greater) return 'CONCURRENT_CONFLICT';
  return v1Greater ? 'V1_DOMINATES' : 'V2_DOMINATES';
}

interface SagaStep {
  name: string;
  execute: () => Promise<void>;
  compensate: () => Promise<void>;
}

export class OrderSagaOrchestrator {
  private executedSteps: SagaStep[] = [];

  async run(steps: SagaStep[]) {
    for (const step of steps) {
      try {
        await step.execute();
        this.executedSteps.push(step);
      } catch (err) {
        console.error(`Step ${step.name} failed! Triggering compensation rollbacks...`);
        await this.rollback();
        throw new Error(`Saga aborted at step: ${step.name}`);
      }
    }
  }

  private async rollback() {
    // Execute compensating transactions in reverse order
    while (this.executedSteps.length > 0) {
      const step = this.executedSteps.pop()!;
      try {
        await step.compensate();
      } catch (compErr) {
        console.error(`CRITICAL: Compensation failed for ${step.name}. Route to manual DLQ!`);
      }
    }
  }
}

export async function processPaymentMessage(msg: KafkaMessage, db: Database) {
  const event = JSON.parse(msg.value.toString());

  // Atomic idempotent UPSERT using database unique constraint
  const result = await db.query(`
    INSERT INTO processed_events (event_id, processed_at)
    VALUES ($1, NOW())
    ON CONFLICT (event_id) DO NOTHING
    RETURNING event_id;
  `, [event.eventId]);

  if (result.rows.length === 0) {
    // Duplicate message redelivery detected! Skip business logic.
    return;
  }

  // Execute business side effect exactly once
  await executeAccountDebit(event.accountId, event.amount);
}

export async function scatterGatherQuery<T>(
  partitions: DatabasePartition[],
  queryFn: (p: DatabasePartition) => Promise<T[]>
): Promise<T[]> {
  // Query all partitions concurrently with a strict timeout boundary
  const promises = partitions.map((p) =>
    Promise.race([
      queryFn(p),
      new Promise<T[]>((_, reject) => setTimeout(() => reject(new Error('Timeout')), 200))
    ])
  );

  const results = await Promise.allSettled(promises);
  const combined: T[] = [];
  for (const r of results) {
    if (r.status === 'fulfilled') combined.push(...r.value);
  }
  return combined;
}

type HashRing struct {
  vnodes   int
  ring     []uint32          // Sorted token slice
  nodeMap  map[uint32]string // Token -> Physical Node ID
  mu       sync.RWMutex
}

func (h *HashRing) GetNode(key string) string {
  h.mu.RLock()
  defer h.mu.RUnlock()
  if len(h.ring) == 0 { return "" }

  hash := fnv32(key)
  // Binary search to find clockwise successor in O(log(N * vnodes))
  idx := sort.Search(len(h.ring), func(i int) bool {
    return h.ring[i] >= hash
  })
  // Wrap around ring if hash exceeds largest token
  if idx == len(h.ring) { idx = 0 }
  return h.nodeMap[h.ring[idx]]
}

