export async function runLeaderElection(etcd: EtcdClient, nodeId: string) {
  const lease = etcd.lease(10); // 10-second TTL
  const election = etcd.election('cluster-scheduler');

  // Attempt to claim leadership
  const campaign = await election.campaign(nodeId, lease);
  console.log(`Node ${nodeId} elected leader! Fencing revision: ${campaign.revision}`);

  // Maintain leadership via continuous keep-alive heartbeats
  lease.on('lost', () => {
    console.error('Leadership lease lost! Stepping down immediately.');
    process.exit(1); // Self-terminate to prevent zombie writes
  });
}

export class RedisLock {
  constructor(private redis: RedisClient, private key: string, private ttlSec = 10) {}

  async acquire(): Promise<string | null> {
    const token = crypto.randomUUID();
    const ok = await this.redis.set(this.key, token, 'NX', 'EX', this.ttlSec);
    return ok === 'OK' ? token : null;
  }

  async release(token: string): Promise<boolean> {
    // Atomic release script: only delete if the token still belongs to this caller
    const script = `
      if redis.call('get', KEYS[1]) == ARGV[1] then
        return redis.call('del', KEYS[1])
      else
        return 0
      end
    `;
    const res = await this.redis.eval(script, 1, this.key, token);
    return res === 1;
  }
}

