// A CRDT that converges monotonically across distributed nodes without coordination
export class GCounter {
  private state: Map<string, number> = new Map();

  constructor(private nodeId: string) {}

  increment(value = 1) {
    const current = this.state.get(this.nodeId) || 0;
    this.state.set(this.nodeId, current + value);
  }

  value(): number {
    let total = 0;
    for (const count of this.state.values()) total += count;
    return total;
  }

  // Merging two nodes is commutative, associative, and idempotent!
  merge(incoming: Map<string, number>) {
    for (const [node, count] of incoming.entries()) {
      const localCount = this.state.get(node) || 0;
      this.state.set(node, Math.max(localCount, count));
    }
  }
}

export class TwoPhaseCommitCoordinator {
  async executeTransaction(participants: ParticipantNode[]): Promise<boolean> {
    // Phase 1: Prepare
    const votes = await Promise.all(
      participants.map(p => p.prepare())
    );

    const allYes = votes.every(v => v === 'VOTE_COMMIT');

    // Write decision durably to coordinator log BEFORE sending Phase 2
    await this.logDecision(allYes ? 'GLOBAL_COMMIT' : 'GLOBAL_ABORT');

    // Phase 2: Commit / Abort
    const decision = allYes ? 'GLOBAL_COMMIT' : 'GLOBAL_ABORT';
    await Promise.all(
      participants.map(p => p.commitOrAbort(decision))
    );

    return allYes;
  }
}
